		int[] ar = array;
		int temp = 0;
		for(int i = 0 ; i < array.length; i++){
			for(int j = i+1 ; j < array.length;j++){
				if(ar[i] > ar[j]){
					temp = ar[i];
					ar[i] = ar[j];
					ar[j] = temp;
				}
			}
		}
		return ar;
	}

}

