import java.io.*;

public class Main {

   public static void main(String[] args) {
      try {
         BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

         while (true) {
            String strAry[] = br.readLine().split(" ");
            int n = Integer.parseInt(strAry[0]);
            int x = Integer.parseInt(strAry[1]);

            if ((n == 0 && x == 0) || (n < 3 || n > 100))
               break;

            System.out.println(combination(n, x));
         }
      }

      catch (Exception e) {
         System.err.println(e);
      }
   }

   private static int combination(int n, int x) {
      int count = 0;
      int a, b, c;
      for (int i = 1; i <= n; i++) {
         for (int j = 1; j <= n; j++) {
            if (i == j)
               break;
            for (int k = 1; k <= n; k++) {
               if (i == k || j == k)
                  break;
               if (i + j + k == x)
                  count++;
            }
         }
      }

      return count;
   }
}

import java.util.Scanner;
import java.util.function.Function;

public class Main {

    public static void main(String[] args) {
        new Main().solve();
    }

    Scanner sc = new Scanner(System.in);

    void solve() {
        String str;
        while (true) {
            str = sc.nextLine();
            String[] sp = str.split(" ");
            int n = Integer.parseInt(sp[0]);
            int x = Integer.parseInt(sp[1]);
            if (isFin(n, x)) break;
            System.out.println(sim(n, x));
        }
    }

    int sim(int n, int x) {
        int cnt = 0;
        for (int i = 1; i <= n; ++i) {
            for (int j = i + 1; j <= n; ++j) {
                if (i == j) continue;
                int k = x - i - j;
                if (i == k || j == k) continue;
                if (j < k && k <= n) {
                    cnt++;
                }
            }
        }
        return cnt;
    }

    boolean isFin(int n, int x) {
        return n == 0 && x == 0;
    }

}

