				//1度目のヒット
				if(!bl1){
					bl1 = true;
				}else{
					//2度目のヒット
					if(!bl2){
						bl2 = true;
					}else{
						//3度目のヒット
						bl3 = true;
					}
				}
			}else{
				//3度未達の場合
				if(!bl3){
					//違う場合全部リセット
					bl1 = false;
					bl2 = false;
					bl3 = false;
				}
			}
		}

		if(bl3){
			System.out.println("Yes");
		}else{
			System.out.println("No");
		}

		sc.close();
	}
}

