public class Main {

	public static void main(String args[]) {

		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int K = sc.nextInt();

		double p = 0;

		if(N < K) {

			for(int i=1;i<=N;i++) {
				if(K%i == 0 && ispow2(K/i)) {
					p += Math.pow(2, -1*((int)(log2(K/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(K/i) + 1)));
				}
			}

			p /= N;
		}else {
			for(int i=1;i<K;i++) {
				if(K%i == 0 && ispow2(K/i)) {
					p += Math.pow(2, -1*((int)(log2(K/i))));
				}else {
					p += Math.pow(2, -1*((int)(log2(K/i) + 1)));
				}
			}
			p /= N;

			p += (double)(N-K+1)/(double)N;
		}
		System.out.println(p);
	}

	public static boolean ispow2(int a) {
		int x = a & (a-1);
		if(x == 0) {
			return true;
		}else {
			return false;
		}
	}

	public static double log2(double a) {
		return Math.log(a)/Math.log(2);
	}
}

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int count = 0;
		int a =0;
		int now =0;
		int beforeK=0;
		while (K>0) {
			count *=2;
			if (N>=K) {
				if (beforeK==0) {
					count +=N-K+1;
				} else {
					count +=beforeK-K;
				}
				beforeK=K;
			}
			if (K>1) {
				K=K/2+K%2;
			} else {
				K/=2;
			}
			a++;
		}
		a--;
		int total = (int) Math.pow(2, a);
		total *=N;
		BigDecimal result = new BigDecimal(count);

		result = result.divide(new BigDecimal(total), 12,RoundingMode.HALF_UP);
		System.out.println(result.toPlainString());
	}
}

