			boolean x = f(c);
			if(x) cnt++;
		}

		System.out.println(cnt);

		sc.close();

	}

	static boolean f(char[] a) {
		boolean x = false;
		int l = a.length - 1;
		int cnt = 0;
		for (int i = 0; i < a.length / 2; i++) {
			if (a[i] == a[l - i])
				cnt++;
		}
		if (cnt == a.length / 2)
			x = true;
		return x;
	}

}

