import java.util.Scanner;

public class Main {
	static Scanner scanner = new Scanner(System.in);
	static int n = scanner.nextInt();
	static int a[][] = new int[2][n];

	@SuppressWarnings("resource")
	public static void main(String args[]) {

		for (int i = 0; i < 2; i++) {
			for (int j = 0; j < n; j++) {
				a[i][j] = scanner.nextInt();
			}
		}

		dfs(0, 0, a[0][0]);

		int max = 0;
		for (int i = 0; i < scores.size(); i++) {
			max = Math.max(scores.get(i), max);
		}

		System.out.println(max);
	}

	static List<Integer> scores = new ArrayList<>();

	private static void dfs(int x, int y, int score) {
		if (x == n - 1 && y == 1) {
			scores.add(score);
			return;
		}

		try {
			score += a[y + 1][x];
			dfs(x, y + 1, score);
			score -= a[y + 1][x];
		} catch (Exception e) {

		}
		try {
			score += a[y][x + 1];
			dfs(x + 1, y, score);
		} catch (Exception e) {

		}

	}
}

import java.util.Scanner;

public class Main {
	static int INF = Integer.MAX_VALUE / 2;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		int[][] adj = new int[2][N];

		for(int i = 0; i < 2; i++) {
			for(int j = 0; j < N; j++) {
				adj[i][j] = sc.nextInt();
			}
		}
		System.out.println(dfs(adj, 0, 0, N));
	}

	static int dfs(int[][] adj, int i, int j, int N) {
		if(i == 1 && j >= N - 1) return adj[i][j];

		if(i == 1 && j < N-1) {
			return adj[i][j] + dfs(adj, i, j+1, N);
		} else if(i==0 && j >= N-1) {
			return adj[i][j] + dfs(adj, i+1, j, N);
		} else {
			return adj[i][j] + Math.max(dfs(adj, i+1, j, N), dfs(adj, i, j+1, N));
		}
	}
}

