import java.util.*;
import java.util.function.*;
import java.math.*;
public class Main {
    public static void main(String[] args){
		Scanner s = new Scanner(System.in);
		int K = s.nextInt();
		int S = s.nextInt();

		int count = 0;
		for(int i = 0; i < K + 1; i++) {
			if(i > S)
				break;
			for(int j = 0; j < K + 1; j++) {
				if(0 <= S - i - j && S - i - j <= K)
					count++;
			}
		}

		System.out.println(count);
    }
}

import java.util.Scanner;

public class Main {

	public static void main(String[] args) {


		Scanner sc = new Scanner(System.in);
		int k = sc.nextInt();
		int s = sc.nextInt();
		int answer = 0;
		for(int x = 0;x <= k;x++) {
			if(x > s) {
				break;
			}
			for(int y = 0;y <= k;y++) {
				if(x + y > s) {
					break;
				}else {
					if(x + y + k >= s) {
						answer++;
					}
				}
			}
		}
		System.out.println(answer);
	}
}

import java.util.Scanner;

public class Main {

    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);

        int K = sc.nextInt();
        int S = sc.nextInt();

        int ans = 0;
        for (int x = 0; x <= K; x++) {
        	for (int y = 0; y <= K; y++) {
        		if (x+y > S)
        			break;

        		if (S - (x + y) <= K) {
        			ans++;
        		}
        	}
        }

        System.out.println(ans);
    }
}

